INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RZN87BRVEIJNI', 'amazon', 'Amazon Customer', 'Super Crispy- Super Delicious!', 'I bought these as a snack during a bland, low fat, gluten free and dairy free diet. Wow. These are so delicious and super crispy! Will definitely buy again and will try the other (non-spicy 🙈) flavors! I’m glad there are sweet alternatives too!', 5, 'positive', 1, 'Thins', '2026-05-01', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture", "gluten_free", "dairy_free_vegan", "good_replacement", "repeat_purchase", "bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
