INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RD5FICY7N1G82', 'amazon', 'Amazon Customer', 'Good for dairyfree glutenfree snack', 'If you don''t have food allergies, I''m guessing you probably won''t like them. But if you do, I can recommend the cheese" flavor. They are soooo good and I am trying hard not to eat all the packages within a week ;) Be aware they are expensive though; packets are pretty small."', 5, 'positive', 1, 'Thins', '2026-03-19', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["gluten_free", "dairy_free_vegan", "allergy_friendly", "packaging"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3H0HGTJJYL1R', 'amazon', 'Amazon Customer', 'Taste is good, but always broken into tiny pieces', 'They''re ok.  Not sure I''d buy again.  I bought them a few times, but each time I said I wouldn''t buy them again!  Very crunchy and thin.  Good ingredients.  Always broken into tiny pieces, so that''s when I say never again.  Taste is pretty good, so I give in and buy again!', 3, 'neutral', 1, 'Thins', '2025-12-25', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["crunch_texture", "repeat_purchase", "broken_crumbs"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RHOWWRV3ZR3BU', 'amazon', 'Amazon Customer', 'Healthy choice', 'First time trying these crackers. I wanted something clean without seed oils or extra ingredients you can’t even read and I found “Every Body Eat” Cheese-less thins. They are gluten free, vegan, and allergy friendly. I love how thin the crackers are but not so thin where they break. They had the perfect amount of salt on each cracker. I love that they are baked and not fried so I can eat them guilt free. I don’t buy too many processed foods but I wanted a healthy conscious choice to pair with my hummus. I definitely recommend these crackers if you want a good snack without all the fake ingredients and best of all it’s a woman owned company! You go ladies!', 4, 'positive', 1, 'Thins', '2026-03-24', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["gluten_free", "dairy_free_vegan", "allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3CCY7PAGRJ1GD', 'amazon', 'Amazon Customer', 'Tasty, crunchy goodness', 'I love these! I have tried the Cheese-Less and Fiery Chile Lime and both were tasty and satisfying. I love the delicate crunch and flavourful taste. I don''t notice the lime so much in the chile lime, but it does pack some nice heat. Will be buying more!', 5, 'positive', 1, 'Thins', '2026-03-23', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RLJXN8VQO128I', 'amazon', 'Amazon Customer', 'Careful when running to buy these!', 'I can not stress this enough, but…..**YUMMMMM** if you’re looking for a GF/DF cheese it’s option, this ain’t it, they’re BETTER!  To me anyways. They’re thinner and crisper, and the right amount of salt on the crisps. I discovered the thins randomly at my local HEB, fell in love at first bite, (my fellow celiacs, IYKYK) went back for another bag and they were out, out for weeks!  Found them on Amazon and got the 2 bags, I’m in love and I will hoard them. If you find me in a quiet corner snackin away, mind ya business!!  8 stars, highly recommend.', 5, 'positive', 1, 'Thins', '2026-05-14', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2KDUEG4ZJ6GG', 'amazon', 'Amazon Customer', 'Definitely not a cheez it substitute', 'They''re ok, not what I was hoping for. I miss being able to eat cheez its but I can no longer have dairy or gluten. These are not light and crispy like those, they are dense and hard like wheat thins. The flavor is not cheesy, definitely taste the garlic though. And they do not have anywhere near as much salt on them as the photo on the package and because I was looking for a salty cheesy snack I could just grab and eat these definitely did not satisfy the craving, were kinda bland, and for the price it''s definitely not worth compromising for me. They aren’t gross or inedible or anything though so, 3 stars.', 3, 'neutral', 1, 'Thins', '2026-04-16', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture", "good_replacement", "bland_flavor", "packaging"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
