INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RTXVKI3MEEQLK', 'amazon', 'Amazon Customer', 'Terrific Cheese-less thin but Terrible packaging', 'Approximately 90% of the Cheese-less thins arrived broken into small pieces. They were packaged in a “Fragile” box but with no paper cushion or bubble wrap. We and our guests love these Every Body Eat Cheese-Less thins but will purchase only from stores now to avoid bad packaging. 🧀', 3, 'neutral', 1, 'Thins', '2025-10-18', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["broken_crumbs", "packaging", "arrived_damaged"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1WQK57T6RLHN9', 'amazon', 'Amazon Customer', 'Not Grain Free', 'I’m giving three stars, because this could be an issue with Amazon and not the seller. I typed in grain free crackers, and this was one of the first items that came up. So bad on me I didn’t check if they were grain free or not. I cannot have grain due to health issues. And it says they’re not returnable, so I’m stuck with these things that I cannot eat.', 3, 'neutral', 1, 'Thins', '2025-08-16', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
