INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RH9MQZ3XLRFDB', 'amazon', 'Amazon Customer', 'GF crackers are very cheesy, close to cheezits flavor', 'GF crackers have lots of flavor.', 5, 'positive', 1, 'Thins', '2026-02-08', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3IRU5S5821237', 'amazon', 'Amazon Customer', 'Cannot believe these are vegan.', 'I’ve asked my husband to buy me vegan snacks for all holidays instead of candy. He bought the Cheese-less Thins variety for Easter, I wasn’t familiar with them but I was certainly game to try them. Hello, new best snack friend! Whoa! I tried 1, then 2 then 8 then…The texture is crunchy with some substance and they’re baked—-BAKED! But it was the impressive flavor that kept me chomping. Vegan cheese is nearly impossible to replicate, ask any vegan, and when I tasted these, the signature warm tang of cheddar lit me up. Not too salty and very satisfying. Recently I had some with my cashew cream tomato soup—-yummm. Even if you’re not vegan you will love the taste and how clean and short the list of ingredients is. These will always have a place of honor in my pantry!', 5, 'positive', 1, 'Thins', '2024-05-18', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture", "dairy_free_vegan", "good_replacement", "too_salty", "false_advertising"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R23YL7CREXEVAV', 'amazon', 'Amazon Customer', 'Taste almost like Cheez-its', 'Slightly addictive because they taste almost like Cheez-its and supposedly healthy. I like this snack quite a lot.', 4, 'positive', 1, 'Thins', '2025-06-22', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["addictive"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2JQUQMAWX1RUO', 'amazon', 'Amazon Customer', 'Smaller bags may preclude binging', 'These are so good that I fall into a trance doing something else and eat the whole bag each time, even though I didn''t want to.  They are the right size, you can pick them out of the bag without hardly looking, and they crunch sastifyingly between your teeth and explode flavor in your mouth, and are yummy the whole time chewing them, and swallow easily.  If I was a snack judge, this product would take the Blue Ribbon.  Their cost per ounce is a bit stiff, which is my only ding.  But as a snack product, I give them my highest rating, and I buy the 6-pack version often.  I don''t want to buy the school lunch size, because that would not be enough.  But if they were just a teensy bit smaller, I wouldn''t feel so bad about polishing off the bag (which, miraculously, finished clean, with no salty dust or other debris lurking in the bottom).  Great product!', 5, 'positive', 1, 'Thins', '2023-09-04', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["great_taste", "crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RWDFK2C7OUQIA', 'amazon', 'Amazon Customer', 'Delicious & Healthier for You! 👍', 'We have been buying these chips from Whole Foods for a while now and the fact that I can just order them on Amazon and have them sent anywhere is awesome! If you''re looking for a good light snack that''s healthy and very flavorful, these are definitely going to become your favorite, haha!', 5, 'positive', 1, 'Thins', '2025-09-09', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "clean_ingredients"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RUCGBBGG1H9S6', 'amazon', 'Amazon Customer', 'It tastes good but don’t expect it to taste like cheeze its', 'Did not irritate my GERD.', 4, 'positive', 1, 'Thins', '2025-07-05', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2GRXTQV93ESCS', 'amazon', 'Amazon Customer', 'Item wasn’t sealed upon opening.', 'Updated: I contacted Every Body Eats with the issue below, and received a phone call regarding the damaged product.  The Co-founder was extremely apologetic and agreed to replace my damaged bag immediately. Just another reason why these are my all-time favorite chips!!Broken chips everywhere inside of the shipping box for one of my package purchases. I love these chips!  And because it is a food item, it cannot be returned.  It is very disappointing that the Amazon person picking the product didn’t catch this blatant sealing error. You can see directly into the package viewing exposed food!!  And from the attached picture, the seal wasn’t torn showing that it was a machine heat seal defect.  Very expensive item to not be able to enjoy it!!', 5, 'positive', 1, 'Thins', '2024-02-02', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["broken_crumbs", "packaging"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3SC5SBLO8VMB4', 'amazon', 'Amazon Customer', 'Love!', 'The best vegan crackers I have found!', 4, 'positive', 1, 'Thins', '2025-06-12', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["dairy_free_vegan"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RF2YDBW1WLSQ5', 'amazon', 'Amazon Customer', 'Love these snacks!', 'I absolutely love these! As someone with a newish dairy and wheat allergy, these are my go-to substitutes for Cheez-Itz! They are thin and crispy, taste cheesy, and salty. They seem to be the best price on Amazon although sometimes they may be $1 less at Sprouts. Definitely worth trying for people with limited choices.', 5, 'positive', 1, 'Thins', '2025-07-21', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture", "allergy_friendly", "good_replacement"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3OGQN1LKXY7UN', 'amazon', 'Amazon Customer', 'Okay taste', 'Taste is okay. I definitely have had better, but these are still edible. Just not my type personally.', 3, 'neutral', 1, 'Thins', '2025-09-07', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2WIMCRLA39S8P', 'amazon', 'Amazon Customer', 'Pricey but Tasty', 'I love them! I do wish they were less expensive and more evenly salted, but they’re my favorite vegan cheese cracker.', 5, 'positive', 1, 'Thins', '2025-12-02', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "dairy_free_vegan"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R5ZOIMTGCZPVL', 'amazon', 'Amazon Customer', 'OBSESSED AND ADDICTED', 'these are TOO good. I will eat an entire bag by myself (which isn’t too crazy because the portion is very small) and still want more- especially as someone with a dairy allergy who used to die for Cheezits. If you like flavor of nutritional yeast then you will love these and their crunchiness, umami and salty flavor, and clean ingredients. My only qualms are the small amount, lack of salt on many of the pieces, and the high price. Would love these in a big family size bag from Costco lol !!', 5, 'positive', 1, 'Thins', '2025-01-12', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["crunch_texture", "allergy_friendly", "clean_ingredients", "addictive", "small_quantity"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R28SA0VL477QRD', 'amazon', 'Amazon Customer', 'Surprisingly good taste for being gluten and dairy free', 'This is my review of Every Body Eat Snack ThinsI personally do not have a problem with gluten or dairy, but I do have friends, and catering clients that do. So, I am always looking for options to make everyone happy. I came across this brand and thought I would give it a try.I am not going to say that they have the same flavor as their gluten and dairy counterparts, but they are very flavorful; either eaten by themselves, or with dips and salsas.Will be keeping a few bags on hand, to use when needed.', 5, 'positive', 1, 'Thins', '2024-02-28', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["dairy_free_vegan", "false_advertising"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2WP6VGYQYV04W', 'amazon', 'Amazon Customer', 'Earthy umami flavor', 'If one is very plant based in their eating then you  probably use nutritional yeast in some form. That''s what the ''cheese'' flavor comes from primarily.  I love nutritional yeast so these crackers are perfect for me. Very crunchy. Perfect amount of salt. Would buy again.', 4, 'positive', 1, 'Thins', '2024-09-15', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["crunch_texture", "repeat_purchase"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3VDY5C11US8PJ', 'amazon', 'Amazon Customer', 'Not cheese flavored, but tasty.', 'Don''t kid yourself that this is cheese, because it''s not.  If you go into it expecting a paprika and garlic flavored cracker, you''ll get that.  And paprika and garlic are good together.  You just have to tell yourself that this is a new food, with it''s own taste, and then they are pretty good.  I wish I had some hummus to try with them, because I suspect that would be really good.', 4, 'positive', 1, 'Thins', '2024-01-09', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["great_taste"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RHABU0X5FXYAO', 'amazon', 'Amazon Customer', 'Love these!!  Healthy and tasty!', 'These taste great tasting, are healthy and really hit the spot!  I have these almost daily as a replacement for unhealthy chips!', 5, 'positive', 1, 'Thins', '2025-11-04', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["great_taste", "good_replacement"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R36QF05NJUW1BQ', 'amazon', 'Amazon Customer', 'Might not be a “bad”snack, but it definitely wasn’t good', 'I was really hoping to like these. I thought they might have a cheez-it like flavor that would satisfy crunch and salt cravings. Unfortunately, they did not. Very thin crackers with no texture. Not sure how to describe the flavor but cheese-y would not be it. I purchased two bags and gave one away. Took the rest of the open one to the office break room.', 2, 'negative', 1, 'Thins', '2025-11-18', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
