INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RNJKMM1DTLHXT', 'amazon', 'Amazon Customer', 'Great tasting', 'They do taste really good, similar to a cheese- it without the sinus infection from the real cheese. I just wished the sea salt stayed attached to the crackers better. If they could fix that it would be amazing', 4, 'positive', 1, 'Thins', '2024-07-29', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RDDUS78T97ZIO', 'amazon', 'Amazon Customer', 'Crunchy dairy & gluten free yumminess', 'A great gluten and dairy free alternative to cheez-its. Now obviously they don’t taste the same as cheez-its, but I like them. They have a great crunch, nice cheese like salty flavor. Healthy substitute for those who cannot eat cheese or gluten. They are on the pricey side - about $5 for a 4oz package. You save a little if you buy in multiple quantity', 5, 'positive', 1, 'Thins', '2025-04-02', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["crunch_texture", "gluten_free", "dairy_free_vegan", "good_replacement", "packaging"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2UQQSMHSBM6S4', 'amazon', 'Amazon Customer', 'The taste and size are perfect and amazing.', 'Being vegan I’m always searching for the perfect vegan Cheez-It cracker. These everybody eat crackers are the absolute best. I’m eating them right now hands-down the best dairy free crackers I’ve ever had strongly recommend them.!', 5, 'positive', 1, 'Thins', '2025-07-10', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["dairy_free_vegan"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R37GL987ZS0L8H', 'amazon', 'Amazon Customer', 'YUM!!!', 'LOVE!!!!!!! I was a cheezeit fein. You could always find me with cheezits. Since being dairy and gluten free I haven’t found anything even close to a cheezit until I found these!!!!! they are expensive but they’re amazing!', 5, 'positive', 1, 'Thins', '2025-06-29', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["great_taste", "gluten_free"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R6SHNPFIK3HR9', 'amazon', 'Amazon Customer', 'Taste So Good', 'So good I love cheez its and these are the best substitute for them. Me and my daughter love them!', 5, 'positive', 1, 'Thins', '2025-09-08', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["great_taste", "good_replacement"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2XBZLWUSGD2FR', 'amazon', 'Amazon Customer', 'Friggin yum!', 'OHHHH heck-to-the-yes over here with these! No, they don''t taste like cheese crackers because there is no cheese in them! However, this is darn close to enjoying some cheese crackers and that cruch! It''s so hard to find a good crunchy snack because I have a good 16 food allergies that I have to stay away from. This right here is a snack that I''ll keep purchasing and enjoy while staying guilt free and true to my body. This is a WIN!', 5, 'positive', 1, 'Thins', '2024-06-05', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture", "allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3K9STMGFP2X7P', 'amazon', 'Amazon Customer', 'So cheesyyy', 'Super tasty and easy to take on the go. If you are looking for the perfect healthy snack, this is it. The clean ingredients will help the urge to eat something worse!', 5, 'positive', 1, 'Thins', '2025-06-22', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "clean_ingredients"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R12RIXY7ONRORN', 'amazon', 'Amazon Customer', 'OMG! The Best!', 'I''ve tried numerous healthy, dairy-free, and gluten-free crackers on the market, but this one stands out as the best. Unlike others that start off well but fail to keep me coming back, this cracker is truly exceptional. It boasts perfect ingredients, an ideal amount of spices, and a satisfying crunch and texture. The hardest part is resisting the urge to eat the whole bag at once.', 5, 'positive', 1, 'Thins', '2024-07-31', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture", "gluten_free", "dairy_free_vegan"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3U6B2HMH46RJY', 'amazon', 'Amazon Customer', 'Amazing taste and quality!!!', 'I’m addicted to this brand!  The Cheese-less crackers are my favorite but I also enjoy the chive and garlic, sea salt chia snack thins.  Their crisp breads are fantastic and I’m currently addicted to their cranberry vanilla cookie bites!', 5, 'positive', 1, 'Thins', '2025-04-21', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture", "addictive"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R17ZZ0A6BJMNDI', 'amazon', 'Amazon Customer', 'A very tasty GF/DF/SF product', 'The product shipped quickly and arrived in great shape (very few broken crackers).The crackers are crunchy and have a good taste.I have it 4 stars instead of 5 stars because of the price per ounce. Products made GF/DF/SF tend to be pricey anyway. Small price to pay to be able to enjoy traditional foods like this I now need to avoid.', 4, 'positive', 1, 'Thins', '2022-09-07', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture", "good_replacement", "broken_crumbs"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3P1TV4M2WTNSS', 'amazon', 'Amazon Customer', 'Cheese flavor is addictive!  Delicious and nutritious', 'These are delicious AND very nutritious.  Also good crumbled on a salad', 5, 'positive', 1, 'Thins', '2025-07-30', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["great_taste", "addictive", "broken_crumbs"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1C1TR18J57B8P', 'amazon', 'Amazon Customer', 'Very good', 'These are so tasty and I have ordered several times from Amazon. Sadly, they typically come with most of the bag crushed into crumbs :(', 3, 'neutral', 1, 'Thins', '2025-03-04', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "broken_crumbs"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R13FNU5597Z8PJ', 'amazon', 'Amazon Customer', 'You don’t even realize there’s no cheese in these', 'You definitely can’t eat just 1 of these crackers. They are thin, crunchy, and oh so good.', 5, 'positive', 1, 'Thins', '2025-07-08', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R26SPS39T8PHOW', 'amazon', 'Amazon Customer', 'taste', 'These are a little spicy too spicy for me.', 3, 'neutral', 1, 'Thins', '2025-04-18', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["too_spicy"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RDANOTVIL3W8J', 'amazon', 'Amazon Customer', 'Delicious Snacks - Love the Variety of Flavors - Worth it!', 'These taste incredible! It is so nice to have a cracker that is dairy and gluten free plus all the ingredients are clean with no nasty oils. I am super impressed! My son and I both really love these crackers. I love the each flavor, but I think the cheese-less one might be my favorite. It has just the right amount of salt too. I am super impressed with the products and the company is very helpful too with answering any questions. I love how light-weight these are and I will be buying again in the near future! Definitely worth it! They also sell crispbreads on their website and they are unbelievably delicious!', 5, 'positive', 1, 'Thins', '2021-05-18', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture", "gluten_free", "value_price", "false_advertising"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
