INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3UKI7G88MW8X1', 'amazon', 'Amazon Customer', 'BUYERS BEWARE! I DON''T RECOMMEND UNLESS USING FOR BIRDFEED!', 'STRONG RECOMMENDATION DON''T BUY ESPECIALLY FOR FAMILY, PARTIES ETC... BUYER BEWARE!!!I WAS TO BRING THESE GLUTEN-FREE DAIRY FREE CRACKERS FOR OUR FAMILY CHRISTMAS 🎄, EACH BAG SAYS 4OZ BUT WHEN I OPENED BAG THERE WERE TONS OF CRUMBS & BROKEN ONES! YOU GET 2 4OZ BAGS EACH ITEM! TOTALLY DISGUSTING OUT OF THE 8OZ THERE WAS 6OZ OF BIRD FEED CRUMBS (I WEIGHED ON FOOD SCALE)!', 1, 'negative', 1, 'Thins', '2025-12-29', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["gluten_free", "dairy_free_vegan", "broken_crumbs"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RTQ52PQQVELA5', 'amazon', 'Amazon Customer', 'Holy moly these are good!', 'Deliciously cheesy tasting, clean ingredients (no seed oils) This company actually uses extra virgin olive oil!!  Thank you thank you thank you from a gal who misses her Cheez Its - now I have these!  Be careful, they’re addicting!', 5, 'positive', 1, 'Thins', '2024-07-11', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["great_taste", "clean_ingredients"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3RDA4DKLE0C7J', 'amazon', 'Amazon Customer', 'Really good for people that have allergies', 'I am gluten intolerant and allergic to dairy, and eggs. These crackers were so nice to find ! They taste like an unnamed Cheeze cracker, and were very tasty. Thank you for making these crackers.😊', 5, 'positive', 1, 'Thins', '2024-09-15', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1D0ZZTA3TYWC8', 'amazon', 'Amazon Customer', 'Like Cheese-its, but not', 'They do taste a lot like cheese-its, and even though they aren’t *exactly* like them, they’re still really good for snacking. I think they’d taste pretty much exactly like cheese-its if they were saltier. They’d be even better if they were cheaper, but in spite of the price, I’ll probably buy more when I’m craving cheese-its next.', 5, 'positive', 1, 'Thins', '2023-11-10', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
