INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R29IBE2ZFWHE0X', 'amazon', 'Amazon Customer', 'I''ve had worse?', 'i mean they, but the flavor is just ok.  Like so many dairy free products there''s too much yeast and onion flavor, with a little burnt component in this case.  Also, the texture is somehow slightly off - they''re reminiscent of very thin dry pasta.  and they need more salt!Earth Balance is SO much better! Or Simple Mill''s tomato/basil if you need gluten free.', 3, 'neutral', 1, 'Thins', '2022-07-18', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["crunch_texture", "gluten_free", "dairy_free_vegan", "bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1EXR6THOET3O0', 'amazon', 'Amazon Customer', 'Fabulous gluten free cracker!', 'These are just great!!  I''ve been wanting a gluten free cracker that tastes like a cheeze it for years and here it is! An obviously more healthy version,  no refined sugar or dairy, they are a thin crispy tasty treat.  Also great that they sell boxes of the smaller size snack version.  Kids can''t get enough of them!  The garlic and chive and sea salt have a heavier texture and are great also.  T', 5, 'positive', 1, 'Thins', '2022-02-12', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "crunch_texture", "gluten_free"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R6U61Y7RD5M5Z', 'amazon', 'Amazon Customer', 'A Thin Crispy Cracker', 'The ingredients are great, very clean and no seed oils. If you like a thin, crisp cracker you may like these.I was disappointed to find the taste to be rather bland and lacking a cheese flavor and won’t be buying again.The calories are a bit high, 130 for 16 crackers.', 2, 'negative', 1, 'Thins', '2025-05-05', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["crunch_texture", "bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
