INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RH33B1WLVBP7A', 'amazon', 'Amazon Customer', 'Fantastic! A fun, healthy snack.', 'There''s a lot to love about these. I''ve tried the Chive & Garlic and Cheese-Less flavors and they''re both delicious. From a health standpoint it''s wonderful that they''re made with olive oil, not palm oil or seed oils, and it''s great that they aren''t fried. As a vegan, I love that they''re made with only plant ingredients, and my gluten-avoiding friends and family members can enjoy them too. And it''s an extra plus to be able to support a small, independent, women and minority-owned business. Will get these again.', 5, 'positive', 2, 'Thins', '2024-02-22', 0, 'No', 'Flavor Name: Chive & GarlicSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["great_taste", "dairy_free_vegan", "palm_oil"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
