INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RTWY1Z8WIX7K5', 'amazon', 'Amazon Customer', 'NOT allergen free!!!! Warning- NIGHTSHADES', 'Contains nightshades which IS a common allergen. It would be easy enough to exclude potato starch for something that is actually not a common allergen.', 1, 'negative', 2, 'Thins', '2025-06-08', 0, 'No', 'Flavor Name: Chive & GarlicSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RY7E8ZJVP1EUO', 'amazon', 'Amazon Customer', 'Very sharp thin corners are dangerous', 'As stated the sharp corners and thin noncrumbly nature of these so called crackers (really chips) can scratch your throat even if you chew well. Especially do not give them to children. They are sharp enough if swallowed accidentally to cut. I bought these at Whole Foods btw, which is owned by Amazon. I got the chili lime ones - They were decent flavor but not spectacular.  I was in a hurry and really did not consider the shape of the crackers, nor could I tell from the package pic how thin they were I guess.', 1, 'negative', 2, 'Thins', '2022-08-24', 0, 'No', 'Flavor Name: Chive & GarlicSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["clean_ingredients", "packaging"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RLRE95NDMRGSL', 'amazon', 'Amazon Customer', 'The best crackers ever!', 'I’ve had a hard time finding good gluten free crackers for many years. These are my favorite! I love the cheese-less flavor as well. I love that they allergy friendly as they are nut-free, soy-free, gluten-free, milk-free and free of so many other allergens. Buy these!!', 5, 'positive', 2, 'Thins', '2024-09-10', 0, 'No', 'Flavor Name: Chive & GarlicSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["gluten_free", "allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
