INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3BV0SSNW932X2', 'amazon', 'Amazon Customer', 'Tasty, fresh, and feel good', 'Discovered these about two months ago, and my family is a big fan. They are tasty but not sickly sweet, and they have a fresh flavor to them. It helps that they work with all my family members'' dietary needs. The one time I binged through almost an entire bag, my joints did not ache like they typically do after too much sugar! I try to keep a bag in the pantry, but they go fast.', 5, 'positive', 6, 'Cookies', '2025-04-07', 0, 'No', '', '', '["great_taste"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
