INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RWDUVIXXZF498', 'amazon', 'Amazon Customer', 'I can''t stop eating these.', 'I don''t know whether it''s one of the allergy-friendly ingredients, or the crisp texture, or the spiciness...but I eat these every day and have no regrets. They are the best-tasting gluten-free crackers that I have tried, and I''ve tried a lot. I wish the other flavors were as delicious to me, but I''m pretty neutral about them. Chili Lime, however? My favoritey fave.', 5, 'positive', 3, 'Thins', '2023-05-06', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["great_taste", "crunch_texture", "gluten_free", "allergy_friendly", "addictive"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R7QKHBJMP6TOJ', 'amazon', 'Amazon Customer', 'Sooooo good', 'I don''t often write reviews but I want this company to stick around so here I am - these are seriously my favorite snacks. I have tried every single flavor and love them all!!!! They are crunchy, SO flavorful, and a healthier option to other chips, etc. The fiery chili lime are my absolute favorite (if you don''t like spicy, stay away, but if you do, order these!!)', 5, 'positive', 3, 'Thins', '2022-08-06', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
