INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1S6CXYYEHCIT7', 'amazon', 'Amazon Customer', 'NEW FAVORITE HEALTHY SNACK', 'I have been looking for a snack that isn''t full of sugar and I''m SO glad I found Every Body Eat. The crackers are the perfect thinness. They are as satisfying as a cheez-its or pretzels but with ingredients you can feel good about putting into your body. I have tried a lot of healthy cracker brands- Hu Kitchen, Simple Mills etc, and these are by far my favorite. I love the Chili Lime flavor for some spice. These will be your new favorite snack!! And on top of it all- I love being able to support a woman-owned business with an inspiring mission.', 5, 'positive', 3, 'Thins', '2021-04-01', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RSLAQ76ZNM838', 'amazon', 'Amazon Customer', 'How are these real?', 'I grew up in a very, very allergic household and can''t believe how good these are. The texture is like a cross between a wheat thin and a cheez-it, they have enough heat to be craveable, and they are PACKED with flavor--lightyears different than the stuff we used to get out of health food stores.If you''re part of an allergy family I don''t know how you can afford to not try these', 5, 'positive', 3, 'Thins', '2021-04-02', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["crunch_texture", "allergy_friendly", "stale", "false_advertising"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R249X360R3FX3X', 'amazon', 'Amazon Customer', 'A+ Snack', 'Love these, they have great taste and check all the boxes for my healthy eating. I have a food allergy in my house hold and knowing I have a great snack food that I don’t have to worry about makes life a bit easier, the only issue I have with them is I enjoy them so much that I eat a whole bag to fast!', 5, 'positive', 3, 'Thins', '2021-04-01', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["great_taste", "allergy_friendly", "stale"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
