INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R347BLZ330XY3D', 'amazon', 'Amazon Customer', 'Spit out the first le.', 'Oh, wow. These are terrible. I read a bunch of great reviews on here about these cookies, so I gave them a shot. What an expensive swing-and-a-miss purchase. I tried the chocolate chip cookies first. I spit out the first one I tried. I still have the other two bags, but that one cookie was so gross I don’t know what to do with them. They’re so expensive! I’d be happy to pay that price if these were delicious. Small companies come and go… and unless this company creates a better product, I’m not sure how long they’re gonna last.', 1, 'negative', 9, 'Cookies', '2025-07-21', 0, 'No', 'Flavor Name: Variety PackSize: 5.5 Ounce (Pack of 3)', '5.5 oz · Pack of 3', '["great_taste"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3D0SLOAQ6MG7W', 'amazon', 'Amazon Customer', 'Honestly obsessed', 'I’m not usually one to leave reviews, but I had to for these. I’m a total snack person (chips, cookies… all of it), but I’ve been trying to find cleaner options that don’t taste like cardboard. These cookie bites are seriously SO good! They’re sweet but not too sweet, don''t have a nasty aftertaste like some other I''ve tried and I love that they''re little so I can eat a ton of them and its still basically like eating one regular cookie...right..?  The super clean ingredients make me feel way better about demolishing the whole bag in one sitting. I am addicted to the Ginger Cinnamon and Cranberry Vanilla especially. They are a little crumbly but in like a shortbread butter melt in your mouth way. Definitely adding these to my snack rotation!', 5, 'positive', 9, 'Cookies', '2025-03-21', 0, 'No', 'Flavor Name: Variety PackSize: 5.5 Ounce (Pack of 3)', '5.5 oz · Pack of 3', '["great_taste", "clean_ingredients", "addictive"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RFUVSEG783IX7', 'amazon', 'Amazon Customer', 'Satisfy your sweet tooth cravings with Every Body Eat Cookie Bites', 'I''ve had a life long sweet tooth but am always looking for cleaner options with ingredients I can feel good about. These Every Body Eat Cookie Bites are hands down the best I''ve found. Taste amazing with just the right amount of sweetness without having that fake after taste you get from some of the other healthy" snacks. They''ve become a new staple for me and the convenience of ordering/quick shipping from Amazon makes it easy to get them."', 5, 'positive', 9, 'Cookies', '2025-03-19', 0, 'No', 'Flavor Name: Variety PackSize: 5.5 Ounce (Pack of 6)', '5.5 oz · Pack of 6', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RL5DTR960AR3F', 'amazon', 'Amazon Customer', 'Healthy & Allergy Safe Snacking', 'These are delicious! Finally a guilt free cookie that actually tastes good. I always keep extra in pantry for my sister who has a laundry list of food allergies. Totally recommend Every Body Eat''s Thins" too. They pair great with your favorite hummus of dip."', 5, 'positive', 9, 'Cookies', '2025-03-31', 0, 'No', 'Flavor Name: Variety PackSize: 5.5 Ounce (Pack of 6)', '5.5 oz · Pack of 6', '["great_taste", "allergy_friendly", "bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RUP7F0AS5KLYG', 'amazon', 'Amazon Customer', 'My new favorite cookies', 'If you’re looking for a satisfying, sweet treat (also healthy!) and still delivers in taste, Every Body Eat Crunchy Cookie Bites are a must-try. I honestly can’t recommend these enough—I’m already stocking up for all my upcoming gatherings! They are DELICIOUS!!!', 5, 'positive', 9, 'Cookies', '2025-03-28', 0, 'No', 'Flavor Name: Variety PackSize: 5.5 Ounce (Pack of 6)', '5.5 oz · Pack of 6', '["great_taste", "crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
