INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R5WAA3YU39LLC', 'amazon', 'Amazon Customer', 'Absolutely Delicious Natural Snack Chips that are Gluten Free and Allergy Friendly!', 'Wow, these snack thins are delicious! We are not usually fans of gluten-free chips. Our son has celiac and had given up on the previous cardboard, chalky-tasting GF chips, so finding yummy snacks he can eat is always a challenge. He loves these, and he couldn’t believe they are gluten-free! Now, the whole family can enjoy them without worrying about allergies or restrictions. INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3EKH6BG4CE4NP', 'amazon', 'Amazon Customer', 'I’m an addict', 'I have zero attachment to the other flavors. They are neither great nor bad. But the cheesy one is amazing. People complain that it is not cheese and they are right. The leading flavor is. Brewers yeast. It is distinct and hits all my notes.', 4, 'positive', 5, 'Thins', '2022-08-23', 0, 'No', 'Flavor Name: Variety PackSize: 4 Ounce (Pack of 4)', '4 oz · Pack of 4', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RYBJSMU7EOQEX', 'amazon', 'Amazon Customer', 'A healthier alternative!', 'We decided to try the variety pack and were pleasantly surprised with both the quality and the taste.  Given that there were four options, it''s no surprise that we liked a couple of them a little bit better than the other two.  Our two favorites were the Chia and the Cheesy (we''ll be ordering more of those two), followed closely by the Chili Lime.  However, once you combine the Chili Lime with some basic store-bought guacamole, it probably ends up on top.  Enjoy!', 5, 'positive', 5, 'Thins', '2024-02-21', 0, 'No', 'Flavor Name: Variety PackSize: 4 Ounce (Pack of 4)', '4 oz · Pack of 4', '["good_replacement"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2RDTQ8CQZR8UJ', 'amazon', 'Amazon Customer', 'Bland', 'Why did you pick this product vs others?:Not my favorite. I got the 4 flavor variety pack. The cheese ones were basically flavorless. I was disappointed in this the most. The Sea Salt Chia ones were ok, but a bit weird tasting, but again a very weak taste. The Fiery Chili Lime was insanely spicy, had a bad after taste and gave me a stomach ache. The Chive and Garlic was the best because it actually had flavor to it. I might consider ordering those again, but the others not so much.', 2, 'negative', 5, 'Thins', '2025-07-10', 0, 'No', 'Flavor Name: Variety PackSize: 4 Ounce (Pack of 4)', '4 oz · Pack of 4', '["bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
