INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RIBZON1T37JQ1', 'amazon', 'Amazon Customer', 'Nutritional Low - Carb Thin Crisps.', 'All healthy ingredients and paper thin  for eating by itself or a dip .Variety pack will determine which one’s I like ; although, I have a feeling that I ‘ll enjoy all flavors in the variety pack.I like the fact that they , two ( 2 ) owners of the company infuse similar ingredients in all products , gluten-free, brown rice , chia seeds , low carb’s , all good stuff.I highly recommend this company and their current products. I’m expecting new products line for dipping sauces soon .', 5, 'positive', 5, 'Thins', '2021-05-19', 0, 'No', 'Flavor Name: Variety PackSize: 4 Ounce (Pack of 4)', '4 oz · Pack of 4', '["crunch_texture", "gluten_free"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
