INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2MNKU2D5FTF3T', 'amazon', 'Amazon Customer', 'So freaking good!', 'I have purchased the variety pack a couple of times direct from their website.  I don''t have allergy issues, but order them anyway because these are SO crave-able!  They have a thin, lovely texture, and the flavor is delicious.  They are a little bit pricey, so they are only a sometimes snack for me-- and I have to shoo my 9 yo away from eating the whole bag.  Glad to see they''re on Amazon, and I see they have free shipping!  Yay!!', 5, 'positive', 5, 'Thins', '2021-01-22', 0, 'No', 'Flavor Name: Variety PackSize: 4 Ounce (Pack of 4)', '4 oz · Pack of 4', '["great_taste", "crunch_texture", "allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RBVFDI75OO0TI', 'amazon', 'Amazon Customer', 'Probably the best hypoallergenic snack I''ve ever had', 'As people with large numbers of food allergies can probably attest, finding snacks that aren''t a few steps off of gently flavored cardboard or painfully expensive can be a challenge. I''m so happy that this much, much tastier option is available. I could eat these snacks any day of the week. Thank you for providing a food that people with allergies can truly enjoy.', 5, 'positive', 5, 'Thins', '2021-04-09', 0, 'No', 'Flavor Name: Variety PackSize: 4 Ounce (Pack of 4)', '4 oz · Pack of 4', '["allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
