INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R13RHI2YTIZ8PI', 'amazon', 'Amazon Customer', 'Great', 'Love these. I am GF and my son has a peanut allergy. Nice consistency and these pack well in a lunch box with an ice pack. Highly recommend this brand. Costco had these in stock for a bit, but when they ran out, I ordered them here. This company also has a product that is like a thin “Cheeze-it”.', 5, 'positive', 14, 'Pretzel', '2026-03-28', 0, 'No', 'Flavor Name: PretzelSize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RFSBI0P8S2MYB', 'amazon', 'Amazon Customer', 'Great work snacks!', 'The perfect snacks now in the perfect portion packs! I love having these on hand at work - crispy, salty and healthy! Fiery Chili Lime are my favorite, and now I can just keep a stash of bags at my desk!', 5, 'positive', 3, 'Thins', '2025-08-11', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
