INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3ECDJKRQU2MBG', 'amazon', 'Amazon Customer', 'Whoa!', 'I originally found these at Whole Foods and fell in love!  I''ve only tried the spicy ones and they are SPICY!  So so so good!', 5, 'positive', 3, 'Thins', '2022-10-13', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["great_taste", "clean_ingredients"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1QWDT806JOC5F', 'amazon', 'Amazon Customer', 'Tasty!', 'I first bought these crackers at Sprouts and the 4 oz bag was $5.99. I think that''s quite expensive. Amazon is the same price though. But they also have a box of (20) bags, that are 1.1 oz per bag. This is the perfect snacking size.These crackers have a slight hint of heat to them after you eat them. I think they''re addicting. They work well with sandwiches, instead of going the usual route with chips. I was searching for a low sodium, low fat tasty snack and this hit the spot.The flavor and crunch is perfect! You get a fair amount in the 1.1 oz bags also, IMHO there''s no reason to get a 4 oz bag because you''ll eat all 4 ounces. I still think they''re a bit pricey but you have to understand that the ingredients are far better for you than the standard fare.For my money, I''ll continue to buy these crackers. I think they''re wonderful!Edit to add: I bought the Fiery Chili Lime flavor.', 5, 'positive', 3, 'Thins', '2022-10-28', 0, 'No', 'Flavor Name: Fiery Chile LimeSize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["great_taste", "crunch_texture", "good_replacement"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
