INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3BW6P47MWYXPE', 'amazon', 'Amazon Customer', 'Save some of these for me!', 'Writing my second review of these every body eat snack treats. Got the 20-pack variety box for back-to-school time. I like these perfectly sized bags measured as 140 calorie portions, ideal for school, work breaks for our gang, and small enough for me to keep one in each front pocket 😁.These seem even toastier than our last batch, fresh as if they are just out of the oven. INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R34N1ZXI44GM5T', 'amazon', 'Amazon Customer', 'Tasty, convenient, and quality ingredients!', 'Loved the flavors in this variety pack. The crackers are so crisp! I liked them all, but the Chive & Garlic and the Cheese-less Thins were my favorites. Coming in a close second were the Sea Salt Crisps. In a category of its own is the Fiery Chile Lime. I’m not a big fan of hot and spicy, but if you are, you’ll love them! The size of each package (1.1 oz.) makes them perfect for school or workday lunches.', 5, 'positive', 5, 'Thins', '2025-09-01', 0, 'No', 'Flavor Name: VarietySize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["great_taste", "crunch_texture", "packaging"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1XZ5JSE9MHK8', 'amazon', 'Amazon Customer', 'Healthy option', 'These are a healthy, grab and go, snack option. I tried these crackers for the first time last week. They come in 4 different flavors in attractive color coded bags. I appreciated the gluten free, dairy free, and no added sugar ingredients. These crackers have a good crunch and a nice variety of flavors. Pack in your kid’s lunch box, slip your purse, or keep in your car for when you need a quick snack. I’m not giving it all five stars because I think the flavors could’ve been a bit stronger.', 4, 'positive', 5, 'Thins', '2025-08-10', 0, 'No', 'Flavor Name: VarietySize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["crunch_texture", "gluten_free", "dairy_free_vegan"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RD6BC94HG8FMX', 'amazon', 'Amazon Customer', 'Good rice cracker option, allergy friendly', 'Tried these today for the first time (cheese-less & chive/garlic) with my tuna salad, and I was pleasantly surprised. They’re crunchy, crispy, and have a good mouth feel. Seems to also be extremely allergy friendly and comes in a lot of fun flavors, which is awesome.I love that the ingredients are clean, simple, and I don’t have to think twice before giving as a snack to my kids/their friends. Writing this review makes me want to open another bag and munch :)', 5, 'positive', 5, 'Thins', '2025-08-05', 0, 'No', 'Flavor Name: VarietySize: 1 Ounce (Pack of 20)', '1 oz · Pack of 20', '["crunch_texture", "allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
