INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1A8J6O0OOK04A', 'amazon', 'p', 'Tasty Healthy Pretzel Chip', 'I have been looking for a seed oil free pretzel option and these checked that box. They are very thin and more like a crisp or chip than a traditional pretzel, which makes them easy to snack on. The sea salt flavor is simple and not overpowering.They feel lighter than most pretzels and worked well on their own and with dips. I appreciated that they are grain free, nut free, and school safe, which makes them easy to keep on hand. A nice swap when you want something crunchy without the usual ingredients found in pretzels.', 5, 'positive', 14, 'Pretzel', '2026-02-23', 1, 'Yes', 'Flavor Name: PretzelSize: 4 Ounce (Pack of 6)', '4 oz · Pack of 6', '["crunch_texture", "allergy_friendly", "seed_oil_free", "kid_friendly", "good_replacement"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
