INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RJEMTOEHWM1PE', 'amazon', 'LW', 'Weird Taste', 'They donâ€™t look or taste like pretzels. They have a weird taste to them, will not be buying again. Maybe will be more tolerable with a dip.', 2, 'negative', 14, 'Pretzel', '2026-01-29', 1, 'Yes', 'Flavor Name: PretzelSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RA8X8TJLF9YC6', 'amazon', 'TDC', 'They Do Taste Like Pretzel', 'The taste I had was appetizing . . .  I''m sure these are very good, but I had an adverse/allergic reaction to that one bite. I have severe corn/maize intolerance and sensitivity and my reaction indicates that there is hidden corn/maize somewhere in the processing or packaging. Caution is recommended for those with corn/maize allergy on any level as corn/maize derivatives have names that would not be suspected as being corn/maize and could be introduced as far back as initial handling/contact of corn/maize with a non-corn/maize ingredient or product.', 1, 'negative', 14, 'Pretzel', '2026-02-19', 1, 'Yes', 'Flavor Name: PretzelSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["allergy_friendly", "packaging_issue"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
