INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2DF4ZAQFZ35VB', 'amazon', 'Amazon Customer', 'Lovely', 'Amazing if you have multiple food sensitivities. I love to dip these in my morning coffee. I haven’t been able to really have store bought cookies in a few years and I was finally able to enjoy one of my guilty pleasures.Of course, not a fit for all allergies, but avoids a lot of common ones like dairy, eggs, wheat and such.Cookies are a little bigger than a quarter in diameter and about 1/3rd in thick. They are nice and textured. They even hold together when dipping in a drink like coffee.', 5, 'positive', 6, 'Cookies', '2026-06-04', 0, 'No', 'Flavor Name: Chocolate ChipSize: 5 Ounce (Pack of 6)', '5 oz · Pack of 6', '["crunch_texture", "allergy_friendly", "stale"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
