INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RJPM5JH3D0TAQ', 'amazon', 'Amazon Customer', 'Dry and crumbly', 'I was diagnosed as a celiac decades ago so I don’t really have non gluten comparisons.  You could make tastier ones at home with the same ingredients that actually feel like a treat.  Give these a miss.', 1, 'negative', 6, 'Cookies', '2025-07-30', 0, 'No', 'Flavor Name: Chocolate ChipSize: 5.5 Ounce (Pack of 1)', '5.5 oz · Pack of 1', '["bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
