INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3QONNRUHTXVS6', 'amazon', 'Amazon Customer', 'So so so good', 'I love these!!! Pretty much everything upsets my stomach but not these! Finally a healthier cookie that doesn’t have artificial sweeteners or inulin! The flavor is buttery and texture is crumbly. They remind me of childhood. 10/10 for me :)Ps: If you’re used to ultra sweet processed cookies, these might just not be for you! Personally I feel like the less sugar, the more I can taste the flavor of the actual ingredients lol', 5, 'positive', 6, 'Cookies', '2025-06-29', 0, 'No', 'Flavor Name: Chocolate ChipSize: 5.5 Ounce (Pack of 1)', '5.5 oz · Pack of 1', '["great_taste", "crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1SZ7LX1NTW4MC', 'amazon', 'Amazon Customer', 'Scrumptious!!', 'These were absolutely delicious. Hit the spot I love cranberry I don’t like too much sugar. I’ve lost 200 pounds and I intend to keep it that way and these hit the Mark absolutely perfect little cookie! They go precisely with a screaming hot 🥵 cup of tea. ☕️ 🫖', 5, 'positive', 7, 'Cookies', '2026-05-08', 0, 'No', 'Flavor Name: Cranberry VanillaSize: 5 Ounce (Pack of 1)', '5 oz · Pack of 1', '["great_taste"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R25J1RK52BCJCU', 'amazon', 'Amazon Customer', 'Problematically Delicious', 'These are about the size of a quarter, but thicker. They have a sandy texture. They are delicious, and it will be very very hard to limit how many you eat in a day. You will be in and out of that bag all day long unless you just flat out give up and eat em all. So, if you are hoping that their diminutive size will prevent you from consuming a bunch of calories all at once, either turn around and go back now, or buy em and just give up altogether, cause making these little gems a part of your healthy diet ain''t gonna happen. Just sayin.', 5, 'positive', 7, 'Cookies', '2026-01-03', 0, 'No', 'Flavor Name: Cranberry VanillaSize: 5.5 Ounce (Pack of 1)', '5.5 oz · Pack of 1', '["great_taste", "crunch_texture"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
