INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('RI03X2WUBROPO', 'amazon', 'Amazon Customer', 'Great GF DF salty snack!', 'I really enjoy these. They have healthy clean gradients. And something that I can eat as it is gluten and dairy free. My husband does not like how these tastes but I do. Anyone who eats a restricted diet without gluten and cheese knows not to expect these to taste like real cheese. I think they did a good job creating a salty snack that taste good while using ingredients that are easy on the stomach', 5, 'positive', 1, 'Thins', '2025-05-25', 0, 'No', 'Flavor Name: Cheese-LessSize: 4 Ounce (Pack of 2)', '4 oz · Pack of 2', '["dairy_free_vegan"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
