INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1B6ZTITMB3SZM', 'amazon', 'Amazon Customer', 'A bit dry but tasty', 'We love their cheese crackers so I was excited to try these.  They are crumbly and dry ( gluten free can be dry but it doesn’t have to be).  They have great flavor.  The ginger one is by far my favorite.  The cranberry one is great crumbled over yogurt.  And the chocolate chip is good crumbled over ice cream.', 3, 'neutral', 9, 'Cookies', '2025-04-30', 0, 'No', 'Flavor Name: Variety Pack', '', '["great_taste", "gluten_free", "broken_crumbs", "bland_flavor"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R327NMUG8SNFET', 'amazon', 'Amazon Customer', '😍Outstanding!🍪', 'If you eat GF, you must try these, they are absolutely the best and I savor each bite. Each bag contains 5 small cookies and that''s all I need to satisfy a sweet tooth moment. Ladies at Every Body Eating...well done these cookies are wonderful!💖', 5, 'positive', 9, 'Cookies', '2025-05-16', 0, 'No', 'Flavor Name: Variety Pack', '', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
