INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R3B7FKSZ8PKGQ9', 'amazon', 'Amazon Customer', 'toddler recommended', 'My toddler has a peanut allergy and it''s hard to find snacks for him that are clean. These are a great option for him and pretty healthy too! They''re in small bags that are easy to bring with us when we''re out and about. He loves the chocolate chip flavor and I personally love the cranberry one! We also love this company''s cheese-less crackers as well!', 5, 'positive', 9, 'Cookies', '2025-04-17', 0, 'No', 'Flavor Name: Variety Pack', '', '["allergy_friendly"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R2QZACSD5R8A1Z', 'amazon', 'Amazon Customer', 'Portion Perfection', 'These are amazing! I know they’re meant for lunches or school treats, but these perfectly portion sized snacks are exactly what I need to treat my sweet tooth mid afternoon.The ginger cookies are super unique and there’s nothing else out there like it. I love how EBE is leaning into this unique and delicious flavor!!', 5, 'positive', 9, 'Cookies', '2025-04-11', 0, 'No', 'Flavor Name: Variety Pack', '', '["great_taste"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R30JK2YMLQR9P9', 'amazon', 'Amazon Customer', 'Delicious cookies!', 'All 3 flavors are delicious! I have been craving cookies but don’t want to feel weighed down or overloaded with sugar. These satisfy my cravings and are hard to believe are gluten free. Love grabbing them as a guilt-free treat every night.Chocolate Chip is my fave flavor, followed by Cranberry Vanilla (delightful combo) and Ginger Cinnamon. The Ginger Cinnamon flavor reminds me of snickerdoodle cookies but with a kick of spice.', 5, 'positive', 9, 'Cookies', '2025-03-31', 0, 'No', 'Flavor Name: Variety Pack', '', '["great_taste", "gluten_free", "false_advertising"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
