INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('R1DF4Z494DZVHM', 'amazon', 'Amazon Customer', 'Delicious, healthy, and full of flavor', 'I really enjoyed this garlic and onion snack. It has a delicious flavor with the perfect balance of seasoning, without tasting artificial or too heavy. It’s a great option when I want something crunchy and tasty while choosing a healthier snack alternative.I love the combination of the bold garlic and onion flavors with the satisfying texture. It’s perfect to enjoy on its own or paired with other foods. A great snack to keep on hand whenever I’m craving something flavorful.Definitely a tasty snack that I would buy again. Highly recommended!', 5, 'positive', 2, 'Thins', '2026-08-04', 0, 'No', 'Flavor Name: Chive & GarlicSize: 4 Ounce (Pack of 1)', '4 oz · Pack of 1', '["great_taste", "crunch_texture", "good_replacement", "repeat_purchase", "stale"]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
