INSERT INTO reviews (id, source, author, title, content, rating, sentiment, taxonomy_id, raw_product_name, date, helpful, verified, variations, pack_size, themes, imported_at, source_file) VALUES ('CSV-20260803-10', 'amazon', 'Katie', 'Terrible Taste and the Smell is even more off putting', 'I had to give it 1 star to write the review - if I could give it negative I would - when we first opened a package of these I thought the dogs brought something into the house - I couldn''t figure out the smell - and then realized it was the product - they smelled terrible and I would rather eat cardboard than these things - which is awful because I bought these from bulk buy store at one point and they were fantastic - my dogs won''t even eat these as treats. I don''t know what changed on the formula but these are not the same as previous versions', 1, 'negative', 14, 'Pretzel', '2026-08-03', 0, 'No', 'Flavor Name: Sea Salt Pretzel Thins', '1 oz · Pack of 20', '[]', '2026-08-23T15:47:32.000Z', 'ebe_review_data_updated.json (D1 migration backfill)');
